// Helper to build a claim record
const makeClaim = (
  id: string, patientId: string, patientName: string, insurance: string,
  claimNum: string | null, procCode: string, detail: string, amount: number,
  status: string, daysSubmitted: number, daysService: number, followUpDays: number,
  notes: string | null, agingStatus: string | null = null, assignedTo: string | null = null,
  collected: number = 0, outstanding: number | null = null, priSec: string = 'Primary',
  repName: string | null = null, refNum: string | null = null
): Claim => ({
  id, patient_id: patientId, patient_name: patientName, insurance_company: insurance,
  claim_number: claimNum, procedure_code: procCode, claim_detail: detail,
  claim_amount: amount, status: status as any, date_submitted: daysAgo(daysSubmitted),
  date_of_service: daysAgo(daysService), date_created: daysAgo(daysSubmitted),
  follow_up_date: followUpDays >= 0 ? daysFromNow(followUpDays) : daysAgo(-followUpDays),
  created_by: 'Staff', completed_by: status.startsWith('Closed') ? 'Admin' : '',
  notes, aging_days: daysSubmitted, archived: false, archived_at: null, archived_by: null,
  collected, outstanding: outstanding ?? amount - collected,
  pri_sec: priSec as any, procedure_types: null, assigned_to: assignedTo,
  rep_name: repName, reference_number: refNum, aging_status: agingStatus as any,
  carrier_phone: null, date_sent_orig: null, structured_notes: [], audit_trail: [],
});

